package com.quizrank.backend.controller;
import com.quizrank.backend.entity.*;import com.quizrank.backend.repository.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.stream.*;
@RestController @RequestMapping("/api/leaderboard") public class LeaderboardController {private final AcademicRecordRepository ar;private final UserRepository ur;private final QuizResultRepository qr;public LeaderboardController(AcademicRecordRepository a,UserRepository u,QuizResultRepository q){ar=a;ur=u;qr=q;}@GetMapping("/department") public List<Map<String,Object>> department(){return ar.findAll().stream().filter(x->"Current".equalsIgnoreCase(x.getSemester())).sorted(Comparator.comparing(AcademicRecord::getCgpa,Comparator.nullsLast(Comparator.reverseOrder()))).map(this::row).toList();}@GetMapping("/batch/{batch}") public List<Map<String,Object>> batch(@PathVariable String batch){Set<Integer> ids=ur.findByRole(User.Role.STUDENT).stream().filter(u->batch.equals(u.getBatch())).map(User::getId).collect(Collectors.toSet());return ar.findAll().stream().filter(x->ids.contains(x.getStudentId())&&"Current".equalsIgnoreCase(x.getSemester())).sorted(Comparator.comparing(AcademicRecord::getCgpa,Comparator.nullsLast(Comparator.reverseOrder()))).map(this::row).toList();}private Map<String,Object> row(AcademicRecord a){User u=ur.findById(a.getStudentId()).orElse(null);Map<String,Object> m=new LinkedHashMap<>();m.put("studentId",a.getStudentId());m.put("userId",u==null?null:u.getUserId());m.put("name",u==null?null:u.getName());m.put("batch",u==null?null:u.getBatch());m.put("cgpa",a.getCgpa());m.put("departmentRank",a.getDepartmentRank());m.put("batchRank",a.getBatchRank());return m;}}
